import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第68章 压痕","description":"","frontmatter":{},"headers":[],"relativePath":"第68章_压痕.md","filePath":"第68章_压痕.md"}'),_={name:"第68章_压痕.md"};function r(u,p,n,s,q,i){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第68章-压痕" tabindex="-1">第68章 压痕 <a class="header-anchor" href="#第68章-压痕" aria-label="Permalink to &quot;第68章 压痕&quot;">​</a></h1><p>那年十月，我们开始寄东西。</p><p>第一次是她寄的。</p><p>一个很普通的纸箱，里面塞了报纸。报纸是从她那边一家华人超市的免费架上拿的，上面还印着超市的促销。</p><p>箱子里是一堆徽章、四张卡片、一副耳机、还有一包她说是&quot;这边很好吃的糖&quot;。</p><p>那包糖到了以后我拆开，是酸的，我含了一颗就扔了。</p><p>我给她发：太酸。</p><p>她说：你居然扔。</p><p>我说：我扔了。</p><p>她说：那是我排了二十分钟买的。</p><p>我说：你排二十分钟买酸糖？</p><p>她说：因为我看你上次说你想吃甜的。</p><p>我回想了一下，我根本没说过我想吃甜的。</p><p>我说：我什么时候说过。</p><p>她说：你九月说的那个&quot;我今天不太舒服，想吃点甜的&quot;。</p><p>我说：那是一句话，我不是在下单。</p><p>她说：我知道你不是在下单。</p><p>她说，我就是看见了。</p><p>我看到那句&quot;我就是看见了&quot;，坐在桌前很久。</p><p>因为她这四个字，比我这一辈子收到的任何一句&quot;我想你&quot;都要重。</p><p>她记住了我随口说的一句话，排了二十分钟，买了，寄过来。</p><p>我那天没有回她&quot;谢谢&quot;。</p><p>我回的是：你那个超市在哪，贵不贵。</p><p>她说：你问这个干什么。</p><p>我说：我记账。</p><p>她说：你记这个干什么，又不是我让你还。</p><p>我说：我知道。</p><p>我说：我记的是我这边能不能买到。</p><p>她说：你买不到。</p><p>我说：我试试。</p><p>她说：你别试，你不许花这个钱。</p><p>我说：为什么。</p><p>她说：因为你没钱。</p><p>我说：我有。</p><p>她说：你有什么，你那点钱我全知道。</p><p>这句话我没法反驳。</p><p>因为她的确全知道。她知道我一百四十块抽的运费，她知道我那个仓库三十多件，她知道我那件外套穿了三年。</p><p>我这辈子被人从头看到脚，只有她一个人。</p><p>而她看完以后说的第一句话是&quot;你不许花这个钱&quot;。</p><p>她寄完那箱东西以后，我就开始想我要回寄什么。</p><p>我想了三个星期。</p><p>她那边的生活里，什么都不缺。我说的是真的什么都不缺：她妈给她钱，她自己会挣，她缺的东西只要她开口，家里就买。</p><p>我要是寄一个她买得起的东西，那件东西就没有意义。</p><p>所以我要寄一个她买不到的。</p><p>有一天夜里我躺在床上，忽然想起高一下那次在县城书店。</p><p>那时候我们刚刚重连上没多久。我们在一个书店里站了四十分钟。</p><p>她翻一本画册。她翻得很快，遇到某一页会用指甲在边上刮一下。</p><p>我问她干什么。</p><p>她说，看它有没有压痕。</p><p>她说，有压痕的是被人翻过很多遍的。</p><p>她说，这种书被人翻过很多遍，说明那一页有人真的看了。</p><p>后来她把一本书立起来给我看。是一页很普通的图，一个空房间，窗开着，窗帘被吹起来。</p><p>我说为什么是这页。</p><p>她说，因为我想进去站一会儿。</p><p>十月末，我开始找那本书。</p><p>我不知道书名。我只记得两件事：那是一本画册，那一页是一个开着窗的房间。</p><p>我先去我们那边的旧书店。</p><p>第一家没有。第二家没有。第三家老板问我，你要哪种画册。</p><p>我说， foreign 的，画的是一间屋子的。</p><p>他说，那太多了。</p><p>我把那页图凭记忆画给他看。</p><p>我画得很难看。</p><p>我画了一个框，框里一个开口的长方形，右边画了一小块歪的东西，我说这是窗帘。</p><p>他看了半天，说，你这个是窗，可是你这个屋子是斜的。</p><p>我说，图就是斜的。</p><p>他说，那你要的是&quot;斜的窗&quot;，我这儿没有。</p><p>后来我在一个网上旧书市场蹲了十一天。</p><p>我发了一条求书，写的是：找一本画册，内页有一张空房间的图，窗开着，窗帘被风吹起来。有的联系。</p><p>我知道这个描述别人一看就当我是神经病。</p><p>第五天，有一个卖家联系我。</p><p>他说，你找的是不是这一本。</p><p>他发了一张图。</p><p>是那页。</p><p>我说，对。</p><p>他说，这本我这儿有，但是我这本不好看，中间有折痕。</p><p>他把那一页翻出来给我看。</p><p>那一页的右下角，有一个很清楚的、指甲掐出来的月牙形压痕。</p><p>我盯着那个痕看了很久。</p><p>我说，我要这本。</p><p>他说，你不嫌旧？</p><p>我说，我就要旧的。</p><p>我买下来，付了三十块。书值十二，剩下十八是邮费和一个纸箱。</p><p>寄出去以前我做了一件事。</p><p>我拿了一支铅笔，在书的最后一页，画了一个很小的窗。</p><p>我没有写字。</p><p>我不写字的理由是：她那边收到东西，封面和里面第一眼看的是不是有字。有字她就要先猜是谁写的。</p><p>画一个窗她不用猜，她知道。</p><p>她收到是十一月四号。</p><p>她那边的下午五点，我这边夜里十二点。</p><p>她说：收到了。</p><p>我说：嗯。</p><p>她说：那页上有痕。</p><p>我说：我知道。</p><p>她说：你怎么找到这本的。</p><p>我说：我找了四家。</p><p>她说：四家？网上四家？</p><p>我说：线下三家，网上十一家。</p><p>她隔了很久。</p><p>久到我以为她又被人叫走了。</p><p>然后她发了一句。</p><p>她说，你凭什么知道我要这本。</p><p>我说：你没说过你要。</p><p>我说：你说的是你想进去站一会儿。</p><p>我说：我想，那本书里那一页如果被人真的看过很多次，那它里面就站着很多人。</p><p>我说：你进去的时候不会一个人。</p><p>她不说话了。</p><p>八点十一分，她发了一条。</p><p>她说，我今天在屋里哭了一会儿。</p><p>我说，你那边现在有人吗。</p><p>她说，有。</p><p>我说，那你别让他们看见。</p><p>她说，我知道。</p><p>她说，我今天没跟任何人说我要哭。</p><p>她说，我就是坐下来想看一下那页，然后它就来了。</p><p>我说，那是压痕。</p><p>她说，你说什么。</p><p>我说，那页本来就有压痕。</p><p>她说，你这个人。</p><p>第二天她上线的时候，第一句跟昨天完全不同。</p><p>她说，那个糖你到底扔了没有。</p><p>我说，扔了。</p><p>她说，那你把那包糖的袋子留下。</p><p>我说，干什么。</p><p>她说，我下次寄的时候放回去，让你扔第二次。</p><p>那天晚上我把这件事抄在本子上。</p><p>我抄的是那句&quot;我就是看见了&quot;。</p><p>抄完我在下面自己加了一行。</p><p>我写：她要什么，她自己从来不讲。她要的是有人先看见。</p>',128)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
